h beeld van een samenleving waarin verhoudingen voortdurend onder druk staan.","work_id":987135006,"evidence":[{"note":"ExactDutchhardcover9789069740522; EduardoMendozaLaVerdadSobreElCasoSavolta1975. Barcelona1917–1919betreft verhaalperiode, niet publicatiejaar. AndereMendoza-titels niet samengevoegd.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p100132367"],"reference":"new-work-dossier-readings-036.json#80","checked_at":"2026-11-03T07:32:53.960Z"},{"type":"original_substantive_source_review","review":"content-review-007.json","sources":["https://data.bibliotheken.nl/id/nbt/p100132367","https://openlibrary.org/works/OL2457396W"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bounded official bulk-source attempt for this exact edition did not yield an identity-approved asset. Preserve existing resolver and document its actual image or neutral placeholder in hosted acceptance; not proof of provider-wide absence.","type":"no_verified_cover_asset_retained","isbn13":"9789069740522","status":"no_verified_asset_retained","attempts":[{"status":"bulk_source_failure_no_retry","coverId":14578848,"receipt":"cover-archive-v2-readback.json","receiptSha256":"0e5eaf5635f1c02234e225a0e3a9e680fc357d0b4dee55ac8eb2522a8c89ba78"},{"status":"new_large_zip_source_failure_no_retry","coverId":14578848,"receipt":"cover-large-zip-readback.json","receiptSha256":"25b7e7114b3c673fdaeb02eca4d527122e92b316794b745200295067523748d0"},{"status":"indexed_bulk_source_unavailable","coverId":14578848,"receipt":"cover-tar-readback.json","receiptSha256":"bd239ad8743b1753337e7794d65733305c254d3b6faf80caab4c3b0dc1edbfb3"}],"checkedAt":"2026-11-03T07:32:53.964Z","editionKey":"/books/OL51012583M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"l