rbondenheid gevaarlijk. Beiden moeten keuzes maken binnen een oorlog die hun persoonlijke wensen blijft doorkruisen.","work_id":987135007,"evidence":[{"note":"Genadeloze geloften9789044368833 is RuthlessVows2023, tweedeLettersOfEnchantment, nietDivineRivals. Iris/Roman/oorlog en geheugenverlies uit gecontroleerde bron; explicietpaperback en Dutch.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p444589481"],"reference":"new-work-dossier-readings-036.json#83","checked_at":"2026-11-03T07:32:53.960Z"},{"type":"original_substantive_source_review","review":"content-review-008.json","sources":["https://data.bibliotheken.nl/id/nbt/p444589481","https://openlibrary.org/works/OL36476271W"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bounded official bulk-source attempt for this exact edition did not yield an identity-approved asset. Preserve existing resolver and document its actual image or neutral placeholder in hosted acceptance; not proof of provider-wide absence.","type":"no_verified_cover_asset_retained","isbn13":"9789044368833","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15130596,"receipt":"cover-archive-v2-readback.json","receiptSha256":"0e5eaf5635f1c02234e225a0e3a9e680fc357d0b4dee55ac8eb2522a8c89ba78"}],"checkedAt":"2026-11-03T07:32:53.965Z","editionKey":"/books/OL60451316M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://data.bibliotheken.nl/id/nbt/p444589481","reviewed_at":"2026-11-03T07:32:53.96+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-036","review_status":"approved","bound_au