d":"OL20748683W","first_publish_year":2020,"native_identity_key":"nlscale:20261102:ol:OL20748683W"},"before_row":null},{"key":{"open_library_edition_id":"OL40229463M"},"seq":45,"relation":"editions","after_row":{"id":987235009,"title":"Utopia Avenue","isbn_10":null,"isbn_13":"9789029092968","work_id":987135009,"cover_id":null,"language":"dut","publisher":"J. M. Meulenhoff","publish_date":null,"open_library_edition_id":"OL40229463M"},"before_row":null},{"key":{"work_id":987135009,"language":"nl"},"seq":46,"relation":"catalog_work_descriptions","after_row":{"text":"In het Londen van de jaren zestig ontstaat de fictieve band Utopia Avenue. Muzikanten met verschillende achtergronden proberen samen een eigen geluid en een publiek te vinden. Hun weg voert van kleine optredens naar grotere podia, terwijl vriendschap, persoonlijke geschiedenis en ambities de groep beïnvloeden. David Mitchell volgt hun korte bestaan in een periode van maatschappelijke en culturele verandering. Het verhaal onderzoekt wat gezamenlijk muziek maken mogelijk maakt en welke druk groeiende bekendheid op mensen kan leggen.","work_id":987135009,"evidence":[{"note":"UtopiaAvenue9789029092968 Dutchhardcover, DavidStephenMitchell/sourceDavidMitchell, KBorigineelSceptre2020. Fictieveband1967–68nietbestaandemuziekbiografie of1984publicatie.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p425880192"],"reference":"new-work-dossier-readings-036.json#87","checked_at":"2026-11-03T07:32:53.960Z"},{"type":"original_substantive_source_review","review":"content-review-008.json","sources":["https://data.bibliotheken.nl/id/nbt/p425880192","https://openlibrary.org/works/OL20748683W"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bounded official bulk-source attempt for this exact edition did not yield an identity-approved asset. Preserve existi